if '</style>' not in s:
    raise RuntimeError('style anchor missing')
s = s.replace('</style>', css + '\n</style>', 1)
anchor = '<section class="section"><div class="wrap features">'
if anchor not in s:
    raise RuntimeError('portfolio insertion anchor missing')
s = s.replace(anchor, html + '\n' + anchor, 1)
p.write_text(s, encoding='utf-8')
print('Multi-niche portfolio lab inserted')
